//! Player scores shared between the match threads of the Pixel Arena server.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

pub type PlayerId = u32;

/// The whole board lives behind one lock, so every operation is atomic and
/// no operation ever takes more than one lock. Clones share the same scores,
/// so each match thread keeps its own handle.
#[derive(Clone, Default)]
pub struct Board {
    state: Arc<Mutex<State>>,
}

#[derive(Default)]
struct State {
    scores: HashMap<PlayerId, i64>,
    total: i64,
}

impl Board {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn join(&self, id: PlayerId, score: i64) {
        let mut state = self.state.lock().unwrap();
        state.scores.insert(id, score);
        state.total += score;
    }

    /// Adds points to a player and to the board total.
    pub fn award(&self, id: PlayerId, points: i64) {
        let mut state = self.state.lock().unwrap();
        let score = state
            .scores
            .get_mut(&id)
            .unwrap_or_else(|| panic!("unknown player {id}"));
        *score += points;
        state.total += points;
    }

    /// Moves points between two players. The board total does not change.
    /// Moving points from a player to the same player changes nothing.
    pub fn transfer(&self, from: PlayerId, to: PlayerId, points: i64) {
        let mut state = self.state.lock().unwrap();
        let from_score = state
            .scores
            .get_mut(&from)
            .unwrap_or_else(|| panic!("unknown player {from}"));
        *from_score -= points;
        let to_score = state
            .scores
            .get_mut(&to)
            .unwrap_or_else(|| panic!("unknown player {to}"));
        *to_score += points;
    }

    pub fn score(&self, id: PlayerId) -> i64 {
        *self
            .state
            .lock()
            .unwrap()
            .scores
            .get(&id)
            .unwrap_or_else(|| panic!("unknown player {id}"))
    }

    pub fn total(&self) -> i64 {
        self.state.lock().unwrap().total
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::thread;

    #[test]
    fn transfer_to_the_same_player_does_not_hang() {
        let board = Board::new();
        board.join(1, 10);
        board.transfer(1, 1, 4);
        assert_eq!(board.score(1), 10);
    }

    #[test]
    fn concurrent_awards_lose_nothing() {
        let board = Board::new();
        for id in 0..4 {
            board.join(id, 0);
        }
        let handles: Vec<_> = (0..8)
            .map(|t| {
                let board = board.clone();
                thread::spawn(move || {
                    for _ in 0..1_000 {
                        board.award(t % 4, 1);
                        board.transfer((t + 1) % 4, t % 4, 1);
                        board.transfer(t % 4, t % 4, 5);
                    }
                })
            })
            .collect();
        for h in handles {
            h.join().unwrap();
        }
        assert_eq!(board.total(), 8_000);
        let sum: i64 = (0..4).map(|id| board.score(id)).sum();
        assert_eq!(sum, 8_000);
    }
}
